import re
from collections import Counter, defaultdict
seq=[]
for line in open('region.fasta'):
    if line.startswith('>'): continue
    seq.append(line.strip())
seq=''.join(seq).upper()
N=len(seq)
comp=str.maketrans('ACGT','TGCA')
def rc(s): return s.translate(comp)[::-1]

# ---- Direct repeats (k=10) at distinct positions ----
print("== Direct repeats (>=10 bp) ==")
k=10
pos=defaultdict(list)
for i in range(0,N-k+1):
    pos[seq[i:i+k]].append(i+1)
reps=[(p,vs) for p,vs in pos.items() if len(vs)>=2]
reps.sort(key=lambda x:-len(x[1]))
for p,vs in reps[:12]:
    print("  %s at positions (1-based) %s"%(p,vs))

# ---- Inverted repeats (stem-loop) simple scan for rho-independent terminator ----
def gcfrac(s):
    return (s.count('G')+s.count('C'))/len(s)
print("\n== Potential stem-loops (inverted repeats) ==")
found=[]
for i in range(0,N-20):
    for L in range(6,13):
        stem=seq[i:i+L]
        for loop in range(3,9):
            j=i+L+loop
            if j+L>N: continue
            if rc(stem)==seq[j:j+L]:
                # hairpin found; check T-stretch after
                tail=seq[j+L:j+L+10]
                tcount=tail.count('T')
                found.append((i+1,j+L, L,loop, tcount, stem))
                break
# report distinct ones with most T after
seen=set(); reported=[]
for f in sorted(found,key=lambda x:-x[4]):
    key=(f[0],f[1])
    if key in seen: continue
    seen.add(key); reported.append(f)
for f in reported[:10]:
    i,j,L,loop,t,stem=f
    print("  stem %d-%d (L=%d loop=%d) rc=%s ... tail T's=%d : %s"%(i,i+L-1,L,loop,rc(stem),t,seq[j:j+12]))

# ---- Promoter -10/-35 anywhere (loose) ----
print("\n== Promoter-like pairs (-35 TTGACA / -10 TATAAT) anywhere ==")
for m35 in re.finditer(r'T[TC]G[AC]CA', seq):
    p35=m35.start()
    for m10 in re.finditer(r'TATA[AT][TC]', seq[p35:p35+25]):
        p10=p35+m10.start(); sp=p10-p35-6
        if 15<=sp<=21:
            print("  -35 %d -10 %d sp=%d : %s"%(p35+1,p10+1,sp,seq[p35:p10+6]))

# ---- Precise coords of the two shorter ORFs (>=132 aa) ----
START='ATG';STOP={'TAA','TAG','TGA'}
def orfs(s,off,strand,minlen=300):
    res=[]
    for i in range(0,len(s)-2,3):
        if s[i:i+3]==START:
            for j in range(i+3,len(s)-2,3):
                if s[j:j+3] in STOP:
                    a=off+i+1;b=off+j+3;L=b-a+1
                    if L>=minlen: res.append((a,b,L,strand))
                    break
    return res
c=[]
for fr in range(3): c+=orfs(seq[fr:],fr,'+')
for fr in range(3): c+=orfs(rc(seq)[fr:],fr,'-')
print("\n== All ORFs >=300 bp ==")
for a,b,L,st in sorted(set(c),key=lambda x:-x[2]):
    print("  %d-%d (%d bp, %d aa) %s"%(a,b,L,L//3,st))
